// queue.js
const items = [];

export function enqueue(item) {
  items.push(item);
}

export async function flushQueue(sink) {
  const batch = items.splice(0, items.length);
  batch.forEach(async (item) => {
    await sink.send(item);
  });
  return batch.length;
}
